let mock = PactBuilder::new("Consumer", "Alice Service")   // use pact_consumer::prelude::*
    .interaction("a retrieve Mallory request", "", |mut i| {
        i.given("there is some good mallory");
        i.request.path("/mallory");
        i.response.content_type("text/plain").body("That is some good Mallory.");
        i
    })
    .start_mock_server(None, None);

let body = reqwest::get(mock.path("/mallory")).await?.text().await?;  // code under test
